"""8A generated bytes only: cleanup explains absence, never transcript success.

Actual removal uses audio_cleanup only, guarded by this test's fresh ownership
registry. Negative missing-source cases rename and retain the generated source.
No existing data/tmp/profile, media decoder, model, process, or service is used.
"""
import hashlib
import json
import os
from pathlib import Path
import sys

import pytest

ROOT = Path(__file__).resolve().parents[1]
sys.path[:0] = [str(ROOT), str(ROOT / "scripts")]
from scripts import audio_segments as audio
from scripts import audio_cleanup as cleanup
from scripts import transcript_results as results

pytestmark = pytest.mark.skipif(os.name != "nt", reason="8A exact-handle cleanup requires Windows")


@pytest.fixture
def day(tmp_path):
    data = tmp_path / "new-task-08A-generated-data"
    folder = data / "audio_generated_2000-01-01"
    folder.mkdir(parents=True)
    return {"data": data, "folder": folder, "owned": {}}


def closed(day):
    data, folder = day["data"], day["folder"]
    number, source = audio.reserve_segment(data, folder)
    payload = (b"task08A-generated-not-media-" + str(number).encode("ascii")) * 240
    with source.open("xb") as stream:
        stream.write(payload)
        stream.flush()
        os.fsync(stream.fileno())
    audio.publish_closed(data, folder, source, number, 1000 + number, 1060 + number)
    day["owned"][source.name] = hashlib.sha256(payload).hexdigest()
    (data / "generated-audio-owner.json").write_text(json.dumps({
        "task": "08A", "purpose": "facts isolated generated bytes", "sources": day["owned"]}, indent=2), encoding="utf-8")
    return source.name


def process(day, name, *, no_speech=False, force=False, text="generated utterance"):
    rows = [] if no_speech else [{"start": 0.0, "end": 1.0, "text": text}]
    return results.process_segment(day["data"], day["folder"], name, lambda _path: (rows, 60.0),
                                   "generated-fake-model", force=force)


def ready(day, *, no_speech=False):
    name = closed(day)
    assert process(day, name, no_speech=no_speech)["state"] == "completed"
    results.rebuild_projection(day["data"], day["folder"])
    assert facts(day, name)["cleanup_eligible"]
    return name


def facts(day, name):
    return results.validate_success(day["data"], day["folder"], name)


def apply_cleanup(day, name):
    # The production primitive can only receive the exact source this fixture
    # generated. Missing leaves remain registered for pending-settlement tests.
    assert name in day["owned"] and day["folder"].parent == day["data"]
    assert (day["data"] / "generated-audio-owner.json").is_file()
    return cleanup.cleanup_segment(day["data"], day["folder"], name)


def never(*_args, **_kwargs):
    pytest.fail("facts/reuse/recovery must not infer, load, or delete another source")


def pending(day, name, monkeypatch):
    def denied(_guard):
        raise PermissionError("generated disposition denied before mutation")
    with monkeypatch.context() as patch:
        patch.setattr(cleanup, "_set_disposition", denied)
        outcome = apply_cleanup(day, name)
    assert outcome["state"] == "pending" and not outcome["deleted"]
    assert (day["folder"] / name).is_file()
    value = json.loads(cleanup.operation_path(day["data"], day["folder"], name).read_bytes())
    assert value["state"] == "pending"
    return value


def retain(path):
    target = path.with_name(path.name + ".retained")
    assert not target.exists()
    path.rename(target)
    return target


def seal_write(path, value):
    payload = {key: item for key, item in value.items() if key != "checksum"}
    raw = json.dumps(payload, sort_keys=True, ensure_ascii=False, separators=(",", ":"), allow_nan=False).encode("utf-8")
    sealed = dict(payload, checksum=hashlib.sha256(raw).hexdigest())
    path.write_text(json.dumps(sealed, sort_keys=True, ensure_ascii=False, separators=(",", ":")) + "\n", encoding="utf-8")


def tree(day):
    return {str(path.relative_to(day["data"])): path.read_bytes() for path in day["data"].rglob("*")
            if path.is_file() and path.name != ".transcribe.run"}


def authorities(day, name):
    data, folder = day["data"], day["folder"]
    paths = [folder / ".segments" / (Path(name).stem + ".json"), results.result_path(data, folder, name),
             results.attempt_path(data, folder, name), *results.projection_paths(data, folder)[:2],
             folder / ".segment-index.json"]
    return {str(path): path.read_bytes() for path in paths}


@pytest.mark.parametrize("no_speech", [False, True], ids=["speech", "no-speech"])
def test_deleted_history_keeps_7a_authority_and_direct_reuse_but_force_refuses_missing_source(day, no_speech):
    name = ready(day, no_speech=no_speech)
    before = authorities(day, name)
    outcome = apply_cleanup(day, name)
    assert outcome["state"] == "deleted" and outcome["deleted"] and outcome["deleted_now"]
    assert not (day["folder"] / name).exists()
    assert authorities(day, name) == before
    value = facts(day, name)
    assert value["current_result"] and value["projection_ready"] and value["audio_cleaned"] and value["history_usable"]
    assert value["cleanup_state"] == "deleted" and not value["reusable"] and not value["cleanup_eligible"]
    snapshot = tree(day)
    assert facts(day, name) == value and tree(day) == snapshot
    reused = results.process_segment(day["data"], day["folder"], name, never, "moved-generated-model")
    assert reused["state"] == "reused" and not reused["inferred"] and not reused["completed_now"]
    forced = results.process_segment(day["data"], day["folder"], name, never, "generated-model", force=True)
    assert forced["state"] == "source_unconfirmed" and not forced["inferred"]
    assert tree(day) == snapshot


def test_pending_missing_leaf_is_usable_but_read_only_facts_never_settle_it(day, monkeypatch):
    name = ready(day)
    pending(day, name, monkeypatch)
    retained = retain(day["folder"] / name)
    snapshot = tree(day)
    value = facts(day, name)
    assert value["audio_cleaned"] and value["history_usable"] and value["current_result"] and value["projection_ready"]
    assert value["cleanup_state"] == "pending" and not value["reusable"] and not value["cleanup_eligible"]
    assert tree(day) == snapshot and retained.is_file()
    with monkeypatch.context() as patch:
        patch.setattr(cleanup, "_set_disposition", never)
        settled = apply_cleanup(day, name)
    assert settled["state"] == "deleted" and settled["deleted"] and not settled["deleted_now"]
    assert facts(day, name)["cleanup_state"] == "deleted" and retained.is_file()


def test_missing_leaf_without_operation_remains_unexplained_and_cannot_create_cleanup_authority(day):
    name = ready(day)
    retained = retain(day["folder"] / name)
    snapshot = tree(day)
    operation = cleanup.operation_path(day["data"], day["folder"], name)
    assert not operation.parent.exists()
    value = facts(day, name)
    assert value["current_result"] and value["projection_ready"]
    assert not value["audio_cleaned"] and not value["history_usable"] and not value["cleanup_eligible"]
    assert value["cleanup_state"] == "none" and tree(day) == snapshot
    assert not operation.parent.exists()
    outcome = apply_cleanup(day, name)
    assert outcome["state"] == "kept" and not outcome["deleted"]
    assert not cleanup.operation_path(day["data"], day["folder"], name).exists()
    assert tree(day) == snapshot and retained.is_file()


@pytest.mark.parametrize("absent", [False, True], ids=["source-present", "source-retained-away"])
@pytest.mark.parametrize("fault", ["checksum", "scope", "generation", "result-digest", "source"])
def test_bad_cleanup_never_authorizes_absence_and_only_blocks_disposal_of_valid_present_source(day, monkeypatch, absent, fault):
    name = ready(day)
    operation = pending(day, name, monkeypatch)
    path = cleanup.operation_path(day["data"], day["folder"], name)
    retain(path)
    if fault == "checksum":
        operation["checksum"] = "0" * 64
        path.write_text(json.dumps(operation), encoding="utf-8")
    else:
        if fault == "scope": operation["scope"]["ino"] += 1
        elif fault == "generation": operation["generation"] = "f" * 32 if operation["generation"] != "f" * 32 else "e" * 32
        elif fault == "result-digest": operation["result_sha256"] = "f" * 64 if operation["result_sha256"] != "f" * 64 else "e" * 64
        else: operation["source"]["sha256"] = "f" * 64
        seal_write(path, operation)
    if absent:
        retain(day["folder"] / name)
    snapshot = tree(day)
    value = facts(day, name)
    assert value["current_result"] and value["projection_ready"]
    assert value["cleanup_state"] == ("invalid" if fault == "checksum" else "conflict")
    assert value["cleanup_reason"] and not value["audio_cleaned"] and not value["cleanup_eligible"]
    assert value["history_usable"] is (not absent) and value["reusable"] is (not absent)
    assert tree(day) == snapshot


def test_deleted_record_with_original_source_present_is_conflict_and_never_deletes_it(day, monkeypatch):
    name = ready(day)
    operation = pending(day, name, monkeypatch)
    path = cleanup.operation_path(day["data"], day["folder"], name)
    retain(path)
    operation["state"] = "deleted"
    seal_write(path, operation)
    snapshot = tree(day)
    value = facts(day, name)
    assert value["reusable"] and value["history_usable"] and value["current_result"]
    assert value["cleanup_state"] == "conflict" and not value["audio_cleaned"] and not value["cleanup_eligible"]
    with monkeypatch.context() as patch:
        patch.setattr(cleanup, "_set_disposition", never)
        assert apply_cleanup(day, name)["state"] == "kept"
    assert tree(day) == snapshot


def test_cleaned_no_speech_remains_usable_after_later_speech_extends_projection_and_counter(day):
    first = ready(day, no_speech=True)
    speech, receipt, _ = results.projection_paths(day["data"], day["folder"])
    assert speech.read_bytes() == b""
    assert apply_cleanup(day, first)["deleted"]
    operation = cleanup.operation_path(day["data"], day["folder"], first).read_bytes()
    old_receipt = receipt.read_bytes()
    second = ready(day)
    assert speech.read_bytes() and receipt.read_bytes() != old_receipt
    assert facts(day, first)["audio_cleaned"] and facts(day, first)["history_usable"]
    assert cleanup.operation_path(day["data"], day["folder"], first).read_bytes() == operation
    assert apply_cleanup(day, second)["deleted"]
    assert all(facts(day, name)["history_usable"] for name in (first, second))
    third = closed(day)
    assert int(Path(third).stem[4:]) > max(int(Path(name).stem[4:]) for name in (first, second))
    assert (day["folder"] / third).is_file()
    assert all(not (day["folder"] / name).exists() for name in (first, second))


@pytest.mark.parametrize("fault", ["intent-missing", "intent-corrupt", "result-corrupt", "receipt-corrupt", "speech-truncated"])
def test_cleanup_record_cannot_replace_current_text_authority(day, fault):
    name = ready(day)
    assert apply_cleanup(day, name)["deleted"]
    speech, receipt, _ = results.projection_paths(day["data"], day["folder"])
    target = (results.attempt_path(day["data"], day["folder"], name) if fault.startswith("intent") else
              results.result_path(day["data"], day["folder"], name) if fault == "result-corrupt" else
              receipt if fault == "receipt-corrupt" else speech)
    retain(target)
    if fault != "intent-missing": target.write_bytes(b"generated truncated evidence")
    snapshot = tree(day)
    value = facts(day, name)
    assert not value["history_usable"] and not value["cleanup_eligible"] and not value["reusable"]
    if fault == "speech-truncated":
        assert value["current_result"] and value["audio_cleaned"] and not value["projection_ready"]
    else:
        assert not value["current_result"] and not value["audio_cleaned"]
    assert tree(day) == snapshot


@pytest.mark.parametrize("force_stage", ["pending", "committed"])
def test_new_force_generation_cannot_inherit_prior_pending_cleanup(day, monkeypatch, force_stage):
    name = ready(day)
    pending(day, name, monkeypatch)
    if force_stage == "pending":
        results.begin_attempt(day["data"], day["folder"], name)
    else:
        assert process(day, name, force=True, text="generated successor")["state"] == "completed"
        results.rebuild_projection(day["data"], day["folder"])
    value = facts(day, name)
    assert not value["audio_cleaned"] and not value["cleanup_eligible"]
    if force_stage == "pending":
        assert not value["current_result"] and not value["history_usable"]
    else:
        assert value["current_result"] and value["history_usable"] and value["cleanup_state"] == "conflict"
    snapshot = tree(day)
    with monkeypatch.context() as patch:
        patch.setattr(cleanup, "_set_disposition", never)
        assert apply_cleanup(day, name)["state"] == "kept"
    assert tree(day) == snapshot and (day["folder"] / name).is_file()


def test_private_current_text_never_opens_the_source_or_grants_source_permission(day, monkeypatch):
    name = ready(day)
    source = day["folder"] / name
    original_open = Path.open

    def guarded_open(path, *args, **kwargs):
        assert path != source, "metadata-only guard must not reopen the DELETE-held source"
        return original_open(path, *args, **kwargs)

    monkeypatch.setattr(Path, "open", guarded_open)
    result, digest, projected = results._current_text(day["data"], day["folder"], name)
    assert projected and result["source"]["file"] == name
    assert digest == hashlib.sha256(results.result_path(day["data"], day["folder"], name).read_bytes()).hexdigest()
